from datetime import datetime, timedelta, date, time

# Helper function to check if a date is a workday (Monday-Friday)
def _is_workday(date_obj: date) -> bool:
    """Returns True if the given date is a Monday, Tuesday, Wednesday, Thursday, or Friday."""
    return date_obj.weekday() < 5 # Monday is 0, Sunday is 6

# Helper function to get the first workday of a specific month
def _get_first_workday_of_month(year: int, month: int) -> date:
    """Finds the first workday (Mon-Fri) of the given year and month."""
    d = date(year, month, 1)
    while not _is_workday(d):
        d += timedelta(days=1)
    return d

# Helper function to get the last day of a specific month
def _get_last_day_of_month(year: int, month: int) -> date:
    """Returns the last day of the given year and month."""
    if month == 12:
        return date(year, 12, 31)
    return date(year, month + 1, 1) - timedelta(days=1)

# Helper function to get the last workday of a specific quarter
def _get_last_workday_of_quarter(year: int, quarter: int) -> date:
    """Finds the last workday (Mon-Fri) of the given year and quarter."""
    # Quarters: Q1=Jan-Mar, Q2=Apr-Jun, Q3=Jul-Sep, Q4=Oct-Dec
    # The last month of a quarter N is N * 3
    last_month_of_quarter = quarter * 3

    # Start from the last day of that month
    d = _get_last_day_of_month(year, last_month_of_quarter)

    while not _is_workday(d):
        d -= timedelta(days=1)
    return d

def delivery_date(start: datetime, description: str) -> datetime:
    """
    Converts a delivery date description to an actual delivery date,
    based on when the meeting started.

    :param start: The datetime object representing when the meeting started.
    :param description: A string describing the delivery date (e.g., "NOW", "ASAP", "EOW", "1M", "Q2").
    :return: A datetime object representing the calculated delivery date.
    :raises ValueError: If the description is unrecognized or contains invalid components.
    """

    # Fixed delivery date descriptions
    if description == "NOW":
        return start + timedelta(hours=2)

    elif description == "ASAP":
        if start.hour < 13:
            # Today at 17:00
            return start.replace(hour=17, minute=0, second=0, microsecond=0)
        else:
            # Tomorrow at 13:00
            return (start + timedelta(days=1)).replace(hour=13, minute=0, second=0, microsecond=0)

    elif description == "EOW":
        weekday = start.weekday() # Monday=0, Tuesday=1, ..., Sunday=6

        if weekday <= 2: # Monday (0), Tuesday (1), Wednesday (2)
            # Delivery on Friday at 17:00
            days_to_add = 4 - weekday # Calculate days until Friday (weekday 4)
            return (start + timedelta(days=days_to_add)).replace(hour=17, minute=0, second=0, microsecond=0)
        elif weekday <= 4: # Thursday (3), Friday (4)
            # Delivery on Sunday at 20:00
            days_to_add = 6 - weekday # Calculate days until Sunday (weekday 6)
            return (start + timedelta(days=days_to_add)).replace(hour=20, minute=0, second=0, microsecond=0)
        else:
            # The instructions explicitly define behavior for Mon-Fri starts.
            # If a Saturday/Sunday `start` is provided for "EOW", it's an undefined case.
            raise ValueError(f"EOW delivery date for weekend start day '{start.strftime('%A')}' is not defined.")

    # Variable delivery date descriptions
    elif description.endswith("M"):
        try:
            n_month = int(description[:-1])
        except ValueError:
            raise ValueError(f"Invalid month number in description: {description}")

        if not (1 <= n_month <= 12):
            raise ValueError(f"Invalid month number '{n_month}' in description: {description}. Must be between 1 and 12.")

        target_year = start.year
        # "Before N-th month": current month is less than N, deliver this year.
        # "After or in N-th month": current month is N or after N, deliver next year.
        if start.month >= n_month:
            target_year += 1

        target_date_obj = _get_first_workday_of_month(target_year, n_month)
        return datetime.combine(target_date_obj, time(8, 0))

    elif description.startswith("Q"):
        try:
            n_quarter = int(description[1:])
        except ValueError:
            raise ValueError(f"Invalid quarter number in description: {description}")

        if not (1 <= n_quarter <= 4):
            raise ValueError(f"Invalid quarter number '{n_quarter}' in description: {description}. Must be between 1 and 4.")

        current_quarter = (start.month - 1) // 3 + 1
        target_year = start.year
        # "Before or in N-th quarter": current quarter is N or before N, deliver this year.
        # "After N-th quarter": current quarter is after N, deliver next year.
        if current_quarter > n_quarter:
            target_year += 1

        target_date_obj = _get_last_workday_of_quarter(target_year, n_quarter)
        return datetime.combine(target_date_obj, time(8, 0))

    else:
        # If the description does not match any known pattern
        raise ValueError(f"Unrecognized delivery date description: {description}")

